  data["draft-orders.json"] = "{\"2024\":{\"note\":\"From the 2024 NFL Combine and Mock Draft doc (2026-10-20): the 2023 regular season as the site has it, the AFC playoffs the sim's favorite in each game, and the real pick trades made before the 2023 kickoff. Teams tied on record rotate each round.\",\"order\":[\"NE\",\"CHI\",\"NYG\",\"GB\",\"WAS\",\"ARI\",\"CAR\",\"TB\",\"DEN\",\"TEN\",\"IND\",\"LA\",\"HOU\",\"PIT\",\"ATL\",\"BUF\",\"NYJ\",\"LV\",\"MIN\",\"DET\",\"DAL\",\"JAX\",\"CLE\",\"MIA\",\"NO\",\"SF\",\"CIN\",\"LAC\",\"BAL\",\"PHI\",\"SEA\",\"KC\"],\"ties\":[[\"CHI\",\"NYG\"],[\"GB\",\"WAS\",\"ARI\"],[\"CAR\",\"TB\",\"DEN\",\"TEN\"],[\"IND\",\"LA\"],[\"HOU\",\"PIT\"],[\"ATL\",\"BUF\",\"NYJ\"],[\"DET\",\"DAL\",\"JAX\"],[\"NO\",\"SF\"]],\"trades\":[{\"round\":1,\"from\":\"CAR\",\"owner\":\"CHI\",\"why\":\"D.J. Moore\"},{\"round\":1,\"from\":\"CLE\",\"owner\":\"HOU\",\"why\":\"Deshaun Watson\"},{\"round\":1,\"from\":\"HOU\",\"owner\":\"ARI\",\"why\":\"the 2023 draft-day trade\"},{\"round\":2,\"from\":\"DEN\",\"owner\":\"NO\",\"why\":\"Sean Payton\"},{\"round\":2,\"from\":\"NO\",\"owner\":\"PHI\",\"why\":\"the 2022 draft-day trade\"},{\"round\":2,\"from\":\"NYJ\",\"owner\":\"GB\",\"why\":\"Aaron Rodgers\"}]}}";

  var cache = {};
  function load(name) {
    var key = String(name).replace(/^\.\//, '').replace(/\.js$/, '');
    if (cache[key]) { return cache[key].exports; }
    if (!sources[key]) { throw new Error('The NFL sim has no ' + name + ' in the browser.'); }
    var module = cache[key] = { exports: {} };
    sources[key].call(module.exports, module, module.exports, load, '');
    return module.exports;
  }

  /* A world kept in memory: files is { name: JSON text }, filled from
     Supabase and saved back by the page. dirty collects what changed. */
  function memoryStore(files, dirty, site) {
    return {
      data: function (name) {
        if (!data[name]) { throw new Error('No ' + name + ' in the NFL sim.'); }
        return JSON.parse(data[name]);
      },
      has: function (world, name) { return Object.prototype.hasOwnProperty.call(files, name); },
      read: function (world, name) { return JSON.parse(files[name]); },
      write: function (world, name, value) { files[name] = JSON.stringify(value); dirty[name] = true; },
      site: function () { return site; }
    };
  }

  window.EGE = window.EGE || {};
  window.EGE.nflSim = {
    /* Points the sim at a world held in memory, and the site at the page. */
    use: function (files, dirty, site) { load('io').use(memoryStore(files, dirty, site || window.EGE)); },
    run: load('run'),
    site: load('site'),
    season: load('season'),
    standings: load('standings'),
    teams: load('teams'),
    trades: load('trades'),
    draftPlan: load('draft-plan')
  };
